"""Parse dotenv-style configuration text into a dictionary.

Supported syntax, one assignment per line::

    # full-line comment
    NAME=value              # unquoted value, inline comment stripped
    export NAME=value       # optional ``export`` prefix
    GREETING="hello\\nworld" # double quotes: escapes and ${VAR} expansion
    RAW='no ${expansion}'   # single quotes: literal text

Blank lines and full-line comments are ignored.  Later assignments to the
same key replace earlier ones.  ``${NAME}`` references are expanded in
unquoted and double-quoted values, first from keys already parsed in the
same document and then from the optional ``environ`` mapping; unknown names
expand to an empty string.
"""

from __future__ import annotations

import re
from typing import Mapping, Optional

from .errors import ParseError

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_.]*\Z")
_INTERPOLATION_RE = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_.]*)\}")
_ESCAPES = {
    "n": "\n",
    "t": "\t",
    "r": "\r",
    '"': '"',
    "\\": "\\",
    "$": "$",
}


def loads(text: str, environ: Optional[Mapping[str, str]] = None) -> dict:
    """Parse configuration ``text`` and return a ``dict`` of string values."""

    values: dict = {}
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        key, raw_value = _split_assignment(stripped, lineno)
        values[key] = _parse_value(raw_value, lineno, values, environ or {})
    return values


def load(path, environ: Optional[Mapping[str, str]] = None) -> dict:
    """Read and parse the configuration file at ``path`` (UTF-8)."""

    with open(path, encoding="utf-8") as handle:
        return loads(handle.read(), environ=environ)


def _split_assignment(line: str, lineno: int) -> tuple:
    if line.startswith("export "):
        line = line[len("export ") :].lstrip()
    if "=" not in line:
        raise ParseError("expected NAME=value", lineno)
    key, raw_value = line.split("=", 1)
    key = key.strip()
    if not _KEY_RE.match(key):
        raise ParseError(f"invalid key {key!r}", lineno)
    return key, raw_value


def _parse_value(
    raw: str, lineno: int, parsed: Mapping[str, str], environ: Mapping[str, str]
) -> str:
    if raw and raw[0] in ("'", '"'):
        if raw[0] == "'":
            return _parse_single_quoted(raw, lineno)
        body = _parse_double_quoted(raw, lineno)
        return _interpolate(body, parsed, environ)
    value = _strip_inline_comment(raw).strip()
    if not value:
        return ""
    return _interpolate(value, parsed, environ)


def _strip_inline_comment(raw: str) -> str:
    """Drop an inline ``# comment`` that follows whitespace."""

    for index, char in enumerate(raw):
        if char == "#" and index > 0 and raw[index - 1] in " \t":
            return raw[:index]
    return raw


def _parse_single_quoted(value: str, lineno: int) -> str:
    if len(value) < 2 or not value.endswith("'"):
        raise ParseError("unterminated single-quoted value", lineno)
    body = value[1:-1]
    if "'" in body:
        raise ParseError("unexpected quote inside single-quoted value", lineno)
    return body


def _parse_double_quoted(value: str, lineno: int) -> str:
    chars = []
    index = 1
    while index < len(value):
        char = value[index]
        if char == "\\":
            if index + 1 >= len(value):
                break
            escaped = value[index + 1]
            if escaped not in _ESCAPES:
                raise ParseError(f"unknown escape sequence \\{escaped}", lineno)
            # Keep an escaped dollar distinguishable from interpolation.
            chars.append("\0" if escaped == "$" else _ESCAPES[escaped])
            index += 2
            continue
        if char == '"':
            if value[index + 1 :].strip():
                raise ParseError("unexpected text after closing quote", lineno)
            return "".join(chars)
        chars.append(char)
        index += 1
    raise ParseError("unterminated double-quoted value", lineno)


def _interpolate(
    value: str, parsed: Mapping[str, str], environ: Mapping[str, str]
) -> str:
    def replace(match: "re.Match[str]") -> str:
        name = match.group(1)
        if name in parsed:
            return parsed[name]
        return environ.get(name, "")

    return _INTERPOLATION_RE.sub(replace, value).replace("\0", "$")

