"""Regression tests for quoted values containing hash characters."""

import pytest
from dotconf import loads, dumps


def test_double_quoted_value_with_hash_and_space():
    """Ensure # preceded by whitespace inside double quotes is preserved."""
    assert loads('PASSWORD="abc # def"') == {"PASSWORD": "abc # def"}


def test_single_quoted_value_with_hash_and_space():
    """Ensure # preceded by whitespace inside single quotes is preserved."""
    assert loads("PASSWORD='abc # def'") == {"PASSWORD": "abc # def"}


def test_round_trip_hash_values():
    """Ensure dumps/loads round-trips values with hashes."""
    values = {"NOTE": "a #b", "TAG": "#x"}
    assert loads(dumps(values)) == values
